#include <print>
#include <vector>

int main() {
    std::vector<int> v = {10, 20, 30, 40, 50};
    v.insert(v.begin(), 999);
    for (int x : v) std::print("{} ", x);
    std::println("← 5 件全被右挪");

    v.erase(v.begin());
    for (int x : v) std::print("{} ", x);
    std::println("← 0 号位走了，右边全体左挪补位");

    std::vector<int> u = {10, 20, 30, 40, 50};
    u.insert(u.begin() + 4, 999);
    for (int x : u) std::print("{} ", x);
    std::println("← 插在 4 号位只有 50 要挪");
    // 最开头插队挪得最多：5 件全体右移
    return 0;
}

